class Schueler
{
  [Pflichtfeld]
  public string Name { get; set; }
      = "";
  public string Klasse { get; set; }
      = "";
  [Pflichtfeld]
  public string? Email { get; set; }
  public string Gruss(string w)
      => $"{w}, {Name}!";
}

var s = new Schueler {
    Name = "Lea", Klasse = "4AHIF" };
Type t = s.GetType();
foreach (var p in t.GetProperties())
  Console.WriteLine(
    $"{p.Name} = {p.GetValue(s)}");
// Name = Lea
// Klasse = 4AHIF
// Email =

var flags = BindingFlags.Public
  | BindingFlags.Instance
  | BindingFlags.DeclaredOnly;
foreach (var m in t.GetMethods(flags))
  Console.Write(m.Name + " ");
// get_Name set_Name get_Klasse
// set_Klasse get_Email set_Email
// Gruss

var g = t.GetMethod("Gruss")!;
Console.WriteLine(
  g.Invoke(s, ["Hallo"]));
// Hallo, Lea!

[AttributeUsage(
  AttributeTargets.Property)]
class PflichtfeldAttribute
  : Attribute { }

static List<string> Pruefe(object o)
{
  var fehler = new List<string>();
  foreach (var p in
      o.GetType().GetProperties())
  {
    bool pflicht = p.GetCustomAttribute
      <PflichtfeldAttribute>() != null;
    if (pflicht && string.IsNullOrEmpty(
        p.GetValue(o) as string))
      fehler.Add($"{p.Name} fehlt");
  }
  return fehler;
}
// Name = "" → Name fehlt, Email fehlt

